}
function sparkline(points, w, h, color, weight) {
  const min = Math.min(...points), max = Math.max(...points);
  const span = (max-min)||1;
  const v = figma.createVector();
  const data = points.map((p,i)=>[ (i/(points.length-1))*w, h - ((p-min)/span)*(h-2) - 1 ]);
  v.vectorPaths = [{windingRule:"NONE", data:"M "+data.map(d=>d[0].toFixed(2)+" "+d[1].toFixed(2)).join(" L ")}];
  v.resize(w,h);
  v.strokes = solid(color); v.strokeWeight = weight||1.5;
  v.strokeCap = "ROUND"; v.strokeJoin = "ROUND";
  v.fills = [];
  return v;
}
