function sparkline(parent,w,h,color,pts){
  const v=figma.createVector();
  const min=Math.min(...pts),max=Math.max(...pts),rg=(max-min)||1;
  v.vectorPaths=[{windingRule:"NONE",data:"M "+pts.map((p,i)=>(i*(w/(pts.length-1))).toFixed(1)+" "+(h-2-((p-min)/rg)*(h-4)).toFixed(1)).join(" L ")}];
  v.strokes=[{type:"SOLID",color}]; v.strokeWeight=1.5; v.strokeCap="ROUND"; v.strokeJoin="ROUND"; v.fills=[];
  v.resize(w,h); parent.appendChild(v); return v;
}

