async function pad(f,yTop){
  const keys=[["1",""],["2","ABC"],["3","DEF"],["4","GHI"],["5","JKL"],["6","MNO"],["7","PQRS"],["8","TUV"],["9","WXYZ"],["*",""],["0",""],["del",""]];
  const padKey=await figma.getNodeByIdAsync("12:29");
  for(let i=0;i<12;i++){
    const r=Math.floor(i/3), c=i%3;
    const k=padKey.createInstance();
    f.appendChild(k); k.x=24+c*113; k.y=yTop+r*72;
    const [main,sub]=keys[i];
    const m=k.findOne(n=>n.name==="Main");
    const s=k.findOne(n=>n.name==="Sub");
    if(main==="del"){ m.characters="\u232B"; s.characters=""; }
    else { m.characters=main; s.characters=sub; }
  }
}
