function txt(parent,str,style,size,color,x,y,w,align){
  const t=figma.createText(); t.fontName={family:"Inter",style}; t.fontSize=size; t.characters=str; t.fills=[{type:"SOLID",color}];
  if(w){t.resize(w,t.height); t.textAlignHorizontal=align||"LEFT"; t.textAutoResize="HEIGHT";}
  parent.appendChild(t); t.x=x; t.y=y; return t;
}
function spark(parent,x,y,w,h,pts,color,weight){
  const v=figma.createVector(); parent.appendChild(v);
  const min=Math.min(...pts), max=Math.max(...pts), rng=(max-min)||1;
  let d="";
  pts.forEach((p,i)=>{ const px=(i/(pts.length-1))*w, py=h-((p-min)/rng)*h; d+=(i===0?"M ":"L ")+px.toFixed(1)+" "+py.toFixed(1)+" "; });
  v.vectorPaths=[{data:d.trim(),windingRule:"NONZERO"}];
  v.strokes=[{type:"SOLID",color}]; v.strokeWeight=weight||2; v.strokeCap="ROUND"; v.strokeJoin="ROUND"; v.fills=[];
  v.x=x; v.y=y; v.resize(w,h);
  return v;
}
async function setTab(f,tb,tbY,idx){
  const names=["Tab/Home","Tab/Portfolio","Tab/Trade","Tab/Market","Tab/Profile"];
  for(let i=0;i<5;i++){
    const tab=tb.findOne(n=>n.name===names[i]);
    const col=i===idx?P.brand:P.faint;
    const lbl=tab.findOne(n=>n.name==="Label"); lbl.fills=[{type:"SOLID",color:col}];
    const icon=tab.findOne(n=>n.name==="Icon");
    const vecs=icon.findAll(n=>n.type==="VECTOR");
    for(const v of vecs){ if(v.fills&&v.fills.length) v.fills=[{type:"SOLID",color:col}]; if(v.strokes&&v.strokes.length) v.strokes=[{type:"SOLID",color:col}]; }
  }
  const ind=tb.findOne(n=>n.name==="ActiveIndicator");
  ind.visible=false;
  const r=figma.createRectangle(); r.resize(24,3); r.cornerRadius=1.5; r.fills=[{type:"SOLID",color:P.brand}];
  f.appendChild(r); r.x=idx*75+(75-24)/2; r.y=tbY+6;
}
async function placeLogoOn(f,rowX,rowY,logoId,fallbackLetter){
  const bx=rowX+8, by=rowY+8, bw=48, bh=48;
  if(logoId){
    const src=await figma.getNodeByIdAsync(logoId);
    const inst=src.createInstance();
    f.appendChild(inst);
    const s=Math.min(bw/src.width,bh/src.height);
    inst.resize(src.width*s,src.height*s);
    inst.x=bx+(bw-inst.width)/2; inst.y=by+(bh-inst.height)/2;
  } else {
    const c=figma.createEllipse(); c.resize(bw,bh); c.fills=[{type:"SOLID",color:P.ink}]; f.appendChild(c); c.x=bx;c.y=by;
    const t=txt(f,fallbackLetter,"Bold",26,P.surface,bx,by,bw,"CENTER");
    t.y=by+(bh-t.height)/2;
  }
}
