const page = await figma.getNodeByIdAsync("5:2");
const f = page.children.find(n=>n.name==="07_Home");
// Row positions: StockRows at y=400,468,536,604,672; WishlistRows at y=788,856,924
// LogoBox is at row.x+0, row.y+12, 40x40; Logo frame at row.x+8, row.y+20, 24x24
// So logo center = row.x+20, row.y+32
const rowYs = [400,468,536,604,672,788,856,924];
const logoNames = ["Logo_Netflix","Logo_Apple","Logo_Facebook","Logo_Bank_of_America",null,"Logo_Amazon","Logo_Adobe","Logo_Facebook"];
const logos = f.children.filter(c=>c.name.startsWith("Logo_"));
const out=[];
// sort logos by y to match rows
logos.sort((a,b)=>a.y-b.y);
for (let i=0;i<logos.length;i++) {
  const l = logos[i];
  const rowY = rowYs.filter((_,j)=>logoNames[j]!==null)[i];
  // target: center at (24+20, rowY+32) = (44, rowY+32), fit in 24x24
  const maxDim = 24;
  const scale = Math.min(maxDim/l.width, maxDim/l.height);
  const nw = l.width*scale, nh = l.height*scale;
  l.resize(nw, nh);
  l.x = 44 - nw/2;
  l.y = rowY + 32 - nh/2;
  out.push(l.name+" -> "+Math.round(nw)+"x"+Math.round(nh)+" @"+Math.round(l.x)+","+Math.round(l.y));
}
return out.join("\n");

